<template>
  <main class="user-page">
    <header class="page-header"><div><span class="eyebrow">ADMIN · IDENTITY GOVERNANCE</span><h1>用户管理</h1><p>管理账号生命周期与管理员权限。角色调整、禁用和密码重置都会先确认并写入审计记录。</p></div><button type="button" class="primary" @click="createOpen = true">创建用户</button></header>
    <section class="summary-grid" aria-label="用户管理概览">
      <article><span>全部用户</span><strong>{{ summary.total }}</strong><small>平台账号总量</small></article><article><span>正常账号</span><strong>{{ summary.active }}</strong><small>当前可登录</small></article><article class="admin"><span>有效管理员</span><strong>{{ summary.admins }}</strong><small>至少保留一名</small></article><article class="danger"><span>已禁用</span><strong>{{ summary.disabled }}</strong><small>Refresh Token 已撤销</small></article>
    </section>
    <div v-if="notice" class="notice" :class="notice.type" role="status"><span>{{ notice.text }}</span><button type="button" aria-label="关闭提示" @click="notice = null">×</button></div>
    <section class="operations-panel">
      <div class="panel-heading"><div><span class="eyebrow">ACCOUNT DIRECTORY</span><h2>账号目录</h2></div><div class="result-count"><strong>{{ filtered.length }}</strong><span>/ {{ users.length }} 位</span></div></div>
      <div class="filter-grid"><label class="search"><span>检索</span><input v-model.trim="filters.keyword" type="search" placeholder="用户名或邮箱" /></label><label><span>角色</span><select v-model="filters.role"><option value="">全部角色</option><option value="admin">管理员</option><option value="student">学习者</option></select></label><label><span>状态</span><select v-model="filters.status"><option value="">全部状态</option><option value="ACTIVE">正常</option><option value="DISABLED">已禁用</option></select></label><label><span>注册时间</span><select v-model="filters.registered"><option value="">全部时间</option><option value="7">最近 7 天</option><option value="30">最近 30 天</option><option value="90">最近 90 天</option></select></label></div>
      <div class="filter-context"><span v-if="activeFilterCount">{{ activeFilterCount }} 个筛选条件生效</span><span v-else>默认按注册时间从新到旧排列</span><div><button v-if="activeFilterCount" type="button" @click="clearFilters">清空筛选</button><button type="button" :disabled="loading" @click="load">刷新</button></div></div>
      <div v-if="loading" class="table-state"><strong>正在读取用户目录</strong><span>同时加载最近审计记录。</span></div><div v-else-if="!filtered.length" class="table-state"><strong>没有匹配的用户</strong><span>调整筛选条件或创建新用户。</span></div>
      <div v-else class="table-scroll"><table><thead><tr><th>用户</th><th>角色</th><th>状态</th><th>学习水平</th><th>注册时间</th><th>最近管理操作</th><th aria-label="操作" /></tr></thead><tbody><tr v-for="user in filtered" :key="user.id"><td><button class="user-link" type="button" @click="selected = user"><strong>{{ user.username }}</strong><span>#{{ user.id }} · {{ user.email || '未填写邮箱' }}</span></button></td><td><span class="role" :class="user.role">{{ roleLabel(user.role) }}</span></td><td><span class="status" :class="user.status.toLowerCase()">{{ statusLabel(user.status) }}</span></td><td>{{ levelLabel(user.level) }}</td><td>{{ formatDate(user.createdAt) }}</td><td><strong>{{ latestAudit(user)?.type ? auditType(latestAudit(user)?.type) : '暂无记录' }}</strong><span>{{ formatDate(latestAudit(user)?.createdAt) }}</span></td><td><button class="detail-button" type="button" @click="selected = user">管理</button></td></tr></tbody></table></div>
    </section>

    <AdminUserDrawer :user="selected" :audits="selected ? auditForUser(audits, selected.id) : []" @close="selected = null" @action="requestAction" />
    <AdminUserConfirm :open="Boolean(pending)" :title="confirmCopy.title" :description="confirmCopy.description" :confirm-text="confirmCopy.button" :danger="confirmCopy.danger" :busy="busy" :guard="guard" @cancel="pending = null" @confirm="executeAction" />

    <Teleport to="body"><div v-if="createOpen" class="modal-layer" role="dialog" aria-modal="true" aria-labelledby="create-user-title"><button class="backdrop" type="button" aria-label="取消创建用户" @click="closeCreate" /><form @submit.prevent="createUser"><span class="eyebrow">NEW ACCOUNT</span><h2 id="create-user-title">创建平台用户</h2><p>账号创建后会生成一次性临时密码，请通过安全渠道交给用户。</p><label><span>用户名</span><input v-model.trim="createForm.username" required minlength="3" autocomplete="off" /></label><label><span>邮箱</span><input v-model.trim="createForm.email" type="email" autocomplete="off" /></label><div class="field-row"><label><span>角色</span><select v-model="createForm.role"><option value="student">学习者</option><option value="admin">管理员</option></select></label><label><span>学习水平</span><select v-model="createForm.level"><option value="beginner">入门</option><option value="intermediate">进阶</option><option value="advanced">高级</option></select></label></div><footer><button type="button" class="quiet" @click="closeCreate">取消</button><button type="submit" :disabled="busy">{{ busy ? '创建中…' : '创建并生成密码' }}</button></footer></form></div></Teleport>
    <Teleport to="body"><div v-if="credential" class="modal-layer" role="dialog" aria-modal="true" aria-labelledby="credential-title"><button class="backdrop" type="button" aria-label="关闭临时密码" @click="clearCredential" /><section class="credential-modal"><span class="eyebrow">ONE-TIME CREDENTIAL</span><h2 id="credential-title">临时密码仅显示一次</h2><p>请立即复制，并通过安全渠道交给 <strong>{{ credential.username }}</strong>。关闭后页面不会保留该密码。</p><div class="password"><code>{{ credential.password }}</code><button type="button" @click="copyCredential">{{ credentialCopied ? '已复制' : '复制密码' }}</button></div><footer><button type="button" @click="clearCredential">我已安全保存</button></footer></section></div></Teleport>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createAdminUser, listAdminAudits, listAdminUsers, resetAdminUserPassword, updateAdminUser } from '../api/adminUsers'
import AdminUserConfirm from '../features/admin/users/AdminUserConfirm.vue'
import AdminUserDrawer from '../features/admin/users/AdminUserDrawer.vue'
import { auditForUser, filterUsers, levelLabel, mutationGuard, roleLabel, statusLabel, summarizeUsers, type AdminAuditRecord, type AdminUserRecord, type UserFilters } from '../features/admin/users/userManagement'
import { getUserFacingError } from '../shared/api/errors'
import { useAuthStore } from '../store/auth'

type Action = 'promote'|'demote'|'disable'|'enable'|'reset'; type Pending = { user: AdminUserRecord; action: Action }; type Notice = { type:'success'|'error'; text:string }
const route=useRoute(); const router=useRouter(); const { currentUser }=useAuthStore()
const users=ref<AdminUserRecord[]>([]); const audits=ref<AdminAuditRecord[]>([]); const loading=ref(true); const busy=ref(false); const selected=ref<AdminUserRecord|null>(null); const pending=ref<Pending|null>(null); const notice=ref<Notice|null>(null); const createOpen=ref(false); const credential=ref<{username:string;password:string}|null>(null); const credentialCopied=ref(false)
const filters=reactive<UserFilters>({keyword:'',role:'',status:'',registered:''}); const createForm=reactive({username:'',email:'',role:'student',level:'beginner'})
const filtered=computed(()=>filterUsers(users.value,filters)); const summary=computed(()=>summarizeUsers(users.value)); const activeFilterCount=computed(()=>Object.values(filters).filter(Boolean).length)
const guard=computed(()=>{ if(!pending.value||pending.value.action==='reset'||pending.value.action==='promote'||pending.value.action==='enable')return ''; const change=pending.value.action==='demote'?{role:'student'}:{status:'DISABLED'}; return mutationGuard(users.value,pending.value.user,currentUser.value?.id as number|undefined,change) })
const confirmCopy=computed(()=>{ const item=pending.value; if(!item)return{title:'',description:'',button:'',danger:false}; const name=`“${item.user.username}”`; const map:Record<Action,{title:string;description:string;button:string;danger:boolean}>={promote:{title:'授予管理员权限？',description:`${name} 将可以访问用户、模型、资源和日志管理功能。`,button:'确认授权',danger:false},demote:{title:'移除管理员权限？',description:`${name} 将变为普通学习者，并立即撤销现有 Refresh Token。`,button:'确认降级',danger:true},disable:{title:'禁用这个账号？',description:`${name} 将无法继续登录，现有 Refresh Token 会立即失效。`,button:'确认禁用',danger:true},enable:{title:'恢复这个账号？',description:`${name} 将重新获得登录权限。`,button:'确认恢复',danger:false},reset:{title:'生成新的临时密码？',description:`${name} 的旧密码和现有 Refresh Token 将立即失效。`,button:'生成临时密码',danger:true}}; return map[item.action] })
onMounted(()=>{syncFromRoute();void load()}); watch(()=>route.query,syncFromRoute); watch(()=>[filters.keyword,filters.role,filters.status,filters.registered],()=>{const query=Object.fromEntries(Object.entries(filters).filter(([,value])=>Boolean(value)));if(JSON.stringify(query)!==JSON.stringify(route.query))void router.replace({query})})
function syncFromRoute(){filters.keyword=typeof route.query.keyword==='string'?route.query.keyword:'';filters.role=['admin','student'].includes(String(route.query.role||''))?String(route.query.role):'';filters.status=['ACTIVE','DISABLED'].includes(String(route.query.status||''))?String(route.query.status):'';filters.registered=['7','30','90'].includes(String(route.query.registered||''))?String(route.query.registered):''}
async function load(){loading.value=true;try{const [userRows,auditRows]=await Promise.all([listAdminUsers(),listAdminAudits()]);users.value=userRows;audits.value=auditRows;if(selected.value)selected.value=userRows.find((item)=>item.id===selected.value?.id)||null}catch(error){notice.value={type:'error',text:getUserFacingError(error,'用户目录加载失败，请稍后重试。')}}finally{loading.value=false}}
function clearFilters(){Object.assign(filters,{keyword:'',role:'',status:'',registered:''})} function requestAction(user:AdminUserRecord,action:Action){pending.value={user,action}} function latestAudit(user:AdminUserRecord){return auditForUser(audits.value,user.id)[0]} function auditType(value?:string|null){return({USER_UPDATE:'角色或状态更新',USER_CREATE:'创建用户',USER_RESET_PWD:'重置密码'}as Record<string,string>)[String(value)]||value||''}
async function executeAction(){const item=pending.value;if(!item||guard.value)return;busy.value=true;try{if(item.action==='reset'){const password=await resetAdminUserPassword(item.user.id);credential.value={username:item.user.username,password}}else{const payload=item.action==='promote'?{role:'admin'}:item.action==='demote'?{role:'student'}:item.action==='disable'?{status:'DISABLED'}:{status:'ACTIVE'};await updateAdminUser(item.user.id,payload)}notice.value={type:'success',text:'用户操作已完成并写入审计记录。'};pending.value=null;await load()}catch(error){notice.value={type:'error',text:getUserFacingError(error,'用户操作失败，请稍后重试。')}}finally{busy.value=false}}
async function createUser(){busy.value=true;try{const user=await createAdminUser({...createForm});const password=await resetAdminUserPassword(user.id);credential.value={username:user.username,password};notice.value={type:'success',text:'用户已创建，请安全保存一次性临时密码。'};closeCreate();await load()}catch(error){notice.value={type:'error',text:getUserFacingError(error,'用户创建失败，请检查用户名和邮箱。')}}finally{busy.value=false}}
function closeCreate(){createOpen.value=false;Object.assign(createForm,{username:'',email:'',role:'student',level:'beginner'})} function clearCredential(){credential.value=null;credentialCopied.value=false} async function copyCredential(){if(!credential.value)return;await navigator.clipboard.writeText(credential.value.password);credentialCopied.value=true} function formatDate(value?:string|null){return value?new Date(value).toLocaleDateString('zh-CN'):'—'}
</script>

<style scoped>
.user-page{display:flex;flex-direction:column;gap:17px;padding:2px 0 36px;color:#203b36}.page-header{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;padding:28px 30px;border:1px solid #dce7e3;border-radius:24px;background:radial-gradient(circle at 88% 12%,rgba(231,219,197,.82),transparent 30%),linear-gradient(135deg,#fbfdfc,#eff6f3)}.eyebrow{color:#71817d;font-size:9px;letter-spacing:.16em}.page-header h1{margin:7px 0;font:700 33px/1.1 Georgia,serif;color:#173d36}.page-header p{max-width:760px;margin:0;color:#637570;font-size:13px;line-height:1.75}.primary{border:0;border-radius:10px;padding:10px 15px;background:#176b5a;color:#fff;font-weight:750;cursor:pointer}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}.summary-grid article{display:grid;gap:4px;padding:17px 19px;border:1px solid #dfe8e4;border-radius:17px;background:#fff}.summary-grid span{color:#6e7e7a;font-size:10px}.summary-grid strong{font:700 27px Georgia,serif;color:#183c35}.summary-grid small{color:#84918e;font-size:9px}.summary-grid .admin{border-color:#d9dfbe}.summary-grid .danger{border-color:#efd4ca}.summary-grid .danger strong{color:#a14834}.notice{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-radius:12px;font-size:12px}.notice.success{background:#e9f6ef;color:#22654e}.notice.error{background:#fff0ec;color:#98402e}.notice button{border:0;background:transparent;color:inherit;font-size:18px;cursor:pointer}.operations-panel{padding:22px;border:1px solid #dce7e3;border-radius:21px;background:#fff;box-shadow:0 10px 35px rgba(30,63,55,.04)}.panel-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.panel-heading h2{margin:5px 0 0;font-size:18px}.result-count{display:flex;align-items:baseline;gap:5px;color:#74837f}.result-count strong{font-size:22px;color:#193d36}.filter-grid{display:grid;grid-template-columns:minmax(220px,2fr) repeat(3,minmax(130px,1fr));gap:10px;padding:14px;border-radius:14px;background:#f2f6f4}.filter-grid label{display:grid;gap:6px;color:#667873;font-size:10px}.filter-grid input,.filter-grid select{width:100%;box-sizing:border-box;border:1px solid #cddbd6;border-radius:9px;padding:10px;background:#fbfcfc;color:#213d38;font:inherit;font-size:12px}.filter-context{display:flex;justify-content:space-between;align-items:center;min-height:38px;color:#74837f;font-size:10px}.filter-context div{display:flex;gap:8px}.filter-context button{border:0;background:transparent;color:#176b5a;font-weight:750;cursor:pointer}.table-state{display:grid;min-height:260px;place-content:center;gap:7px;text-align:center;border:1px dashed #ccd9d5;border-radius:15px;background:#fafcfb;color:#71807c}.table-state strong{color:#27433d}.table-scroll{overflow-x:auto;border:1px solid #dfe8e5;border-radius:15px}table{width:100%;min-width:1060px;border-collapse:collapse}th{padding:11px 13px;text-align:left;color:#6d7d79;background:#f3f7f5;border-bottom:1px solid #dfe8e5;font-size:9px;letter-spacing:.08em;text-transform:uppercase}td{padding:13px;border-bottom:1px solid #e8efec;color:#314a45;font-size:11px;vertical-align:middle}tbody tr:hover{background:#f7faf9}td>strong,td>span{display:block}.user-link{display:grid;gap:4px;max-width:260px;padding:0;border:0;background:transparent;color:#24423b;text-align:left;cursor:pointer}.user-link span,td>span{color:#74837f;font-size:9px}.role,.status{display:inline-flex!important;padding:4px 8px;border-radius:99px;font-size:10px!important;font-weight:750}.role.admin{background:#fff0df;color:#8c5520}.role.student{background:#e7f3ef;color:#286451}.status.active{background:#e4f5ed;color:#176449}.status.disabled{background:#fff0ec;color:#9d402f}.detail-button{border:0;border-radius:8px;padding:7px 10px;background:#e6efec;color:#315c52;font-weight:750;cursor:pointer}.modal-layer{position:fixed;inset:0;z-index:4700;display:grid;place-items:center;padding:18px}.backdrop{position:absolute;inset:0;border:0;background:rgba(7,25,23,.58)}.modal-layer form,.credential-modal{position:relative;width:min(480px,100%);box-sizing:border-box;padding:24px;border-radius:18px;background:#fff;box-shadow:0 25px 80px rgba(0,0,0,.25)}.modal-layer h2{margin:7px 0 8px;color:#173d36;font-size:21px}.modal-layer p{margin:0;color:#637570;font-size:11px;line-height:1.7}.modal-layer form>label,.field-row label{display:grid;gap:6px;margin-top:13px;color:#5d716c;font-size:10px}.modal-layer input,.modal-layer select{width:100%;box-sizing:border-box;border:1px solid #cddbd6;border-radius:9px;padding:10px;background:#fbfcfc;font:inherit}.field-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.modal-layer footer{display:flex;justify-content:flex-end;gap:8px;margin-top:19px}.modal-layer footer button,.password button{border:0;border-radius:9px;padding:9px 13px;background:#176b5a;color:#fff;font-weight:750;cursor:pointer}.modal-layer footer .quiet{background:#e7efec;color:#425e57}.password{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:16px;padding:13px;border-radius:11px;background:#173f38;color:#fff}.password code{overflow:auto;font-size:13px}.password button{flex-shrink:0;background:#d9ece6;color:#174d40}.credential-modal strong{color:#27463f}@media(max-width:900px){.filter-grid{grid-template-columns:1fr 1fr}.search{grid-column:1/-1}}@media(max-width:720px){.page-header{align-items:flex-start;flex-direction:column;padding:22px}.page-header h1{font-size:29px}.page-header .primary{width:100%}.summary-grid{grid-template-columns:1fr 1fr}.operations-panel{padding:16px}}@media(max-width:420px){.summary-grid,.filter-grid,.field-row{grid-template-columns:1fr}.search{grid-column:auto}.password{align-items:stretch;flex-direction:column}}
</style>
